'use strict';
(() => {
const DATA = window.STUDY_DATA;
if (!DATA?.subjects?.length) { document.getElementById('main').innerHTML='<div class="empty-state"><h1>Study content could not load</h1><p>Keep data.js beside index.html, then refresh this page.</p></div>'; return; }
const KEY='studyos-v1', $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=v=>{const t=document.createElement('div');t.innerHTML=v??'';return t.textContent.trim();};
const short=(v,n=105)=>{v=plain(v);return v.length>n?v.slice(0,n).trim()+'…':v;};
const dayKey=(date=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const defaults=()=>({version:1,theme:'light',read:{},saved:{},answers:{},cards:{},checks:{},activity:[],focusDays:{},timer:{remaining:1500,end:null,duration:1500},goal:45,quizSession:null,examSession:null,customTasks:[],notes:{}});
let state; try {state={...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch {state=defaults();}
let storageWarned=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarned){storageWarned=true;toast('Browser storage is full. Export your progress from Settings.');}}}
const subjects=DATA.subjects, modules=subjects.flatMap(s=>s.modules.map(m=>({...m,subjectId:s.id}))), questions=subjects.flatMap(s=>s.questions.map(q=>({...q,subjectId:s.id}))), cards=subjects.flatMap(s=>s.flashcards.map(c=>({...c,subjectId:s.id}))), written=subjects.flatMap(s=>s.written.map(w=>({...w,subjectId:s.id}))), sources=subjects.flatMap(s=>s.sources.map(x=>({...x,subjectId:s.id})));
const bySubject=id=>subjects.find(s=>s.id===id),byModule=id=>modules.find(m=>m.id===id),byQuestion=id=>questions.find(q=>q.id===id),byWritten=id=>written.find(q=>q.id===id);
const subjectIcons={pt:'shield',ns:'network',devsecops:'layers',mem:'briefcase'};
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M4 3h12a4 4 0 0 1 4 4v14H8a4 4 0 0 1-4-4V3Zm0 14a4 4 0 0 1 4-4h12M8 3v10',search:'m21 21-5-5M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',calendar:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4',cards:'m8 3 12 3-4 15-12-3L8 3Zm-4 3L2 16l3 1M9 8l6 2m-7 3 5 1',target:'M22 12a10 10 0 1 1-3-7M17 12a5 5 0 1 1-5-5m0 5L22 2m-5 0h5v5',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6',network:'M9 3h6v6H9zM2 16h6v6H2zM16 16h6v6h-6zM12 9v4M5 16v-3h14v3',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',briefcase:'M3 7h18v14H3zM8 7V3h8v4M3 12a24 24 0 0 0 18 0M12 11v4',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM21 2v4M19 4h4',bookmark:'M6 3h12v19l-6-4-6 4V3Z',folder:'M3 5h7l2 3h9v13H3V5Z',chart:'M4 3v18h17M8 16v-5m5 5V7m5 9V4',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z',sun:'M12 3V1m0 22v-2M3 12H1m22 0h-2M5 5 3 3m18 18-2-2M5 19l-2 2M21 3l-2 2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',play:'m8 4 13 8-13 8V4Z',pause:'M7 4h3v16H7zM14 4h3v16h-3z',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',menu:'M4 6h16M4 12h16M4 18h16',graduate:'m2 9 10-5 10 5-10 5L2 9Zm4 3v6l6 3 6-3v-6m4-3v9',flame:'M12 3c0 5 7 5 7 11a7 7 0 0 1-14 0c0-3 2-6 4-7 0 4 3 4 3 4s3-3 0-8Z',file:'M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8m-8 4h6',more:'M5 12h.01M12 12h.01M19 12h.01',plus:'M12 4v16M4 12h16',keyboard:'M2 5h20v14H2zM6 9h.01M10 9h.01M14 9h.01M18 9h.01M6 13h.01M10 13h.01M14 13h.01M18 13h.01M7 16h10',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',heart:'M20 4c-3-3-7-1-8 1-1-2-5-4-8-1-5 5 0 11 8 17 8-6 13-12 8-17Z'};
function icon(n,cls=''){return `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;}
const arrow=()=>icon('arrow');
const btn=(text,action,kind='primary',extra='')=>`<button class="button ${kind}" ${action?`data-action="${action}"`:''} ${extra}>${text}</button>`;
const link=(label,route,cls='button primary')=>`<a class="${cls}" href="#${route}">${label}</a>`;
function activity(type,title,subjectId=''){state.activity.unshift({type,title,subjectId,date:new Date().toISOString()});state.activity=state.activity.slice(0,80);save();}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('check')+`<span>${esc(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),3800);}
function pct(s){const total=s.modules.reduce((n,m)=>n+m.sections.length,0);const done=s.modules.reduce((n,m)=>n+m.sections.filter((_,i)=>state.read[`${m.id}:${i}`]).length,0);return Math.round(done/Math.max(total,1)*100);}
function modulePct(m){return Math.round(m.sections.filter((_,i)=>state.read[`${m.id}:${i}`]).length/Math.max(m.sections.length,1)*100);}
function nextModule(s){return s.modules.find(m=>modulePct(m)<100)||s.modules[0];}
function formatDate(v,opts={month:'short',day:'numeric'}){return new Date(v.length===10?v+'T12:00:00+05:30':v).toLocaleDateString('en-GB',{timeZone:'Asia/Colombo',...opts});}
function daysUntil(v){return Math.round((Date.parse(v.slice(0,10))-Date.parse(dayKey()))/86400000);}
function examLabel(s){const d=daysUntil(s.examDate);return d>=0?`${d} days to exam`:'Exam date passed';}
function navigate(route){if(location.hash==='#'+route)render();else location.hash=route;closeModal();closeSidebar();}
let appliedHash=null;
let route='dashboard',subjectFilter='all',cardFilter='all',cardIndex=0,cardFlipped=false,cardReview='all',libraryFilter='all',libraryQuery='',writtenFilter='all',quizSetup={subject:'all',count:10,mode:'all'},searchIndex=null;
const routeTitle={dashboard:'Overview',subjects:'My subjects',practice:'Practice questions',flashcards:'Flashcards',exams:'Mock exams',planner:'Study planner',library:'Resource library',saved:'Saved notes',written:'Written practice'};
function sidebar(){const active=route.split('/')[0];const item=(name,id,label,count='')=>`<a class="nav-link ${active===id?'active':''}" href="#${id}">${icon(name)}<span>${label}</span>${count!==''?`<span class="nav-count">${count}</span>`:''}</a>`;
$('#sidebar').innerHTML=`<a href="#dashboard" class="brand" aria-label="StudyOS home"><span class="brand-mark">${icon('graduate')}</span><span class="brand-name">study<span>os</span><span class="brand-dot">.</span></span></a><div class="workspace-label"><span class="workspace-indicator"></span> YOUR PERSONAL WORKSPACE</div><div class="nav-label">WORKSPACE</div><nav>${item('grid','dashboard','Overview')}${item('book','subjects','My subjects','04')}${item('calendar','planner','Study planner')}${item('bookmark','saved','Saved notes',Object.values(state.saved).filter(Boolean).length)}</nav><div class="nav-label">LEARN & PRACTISE</div><nav>${item('target','practice','Practice questions')}${item('cards','flashcards','Flashcards')}${item('file','written','Written practice')}${item('clock','exams','Mock exams')}${item('folder','library','Resource library')}</nav><div class="sidebar-bottom"><div class="sidebar-promo"><div class="promo-icon">${icon('sparkles')}</div><strong>A little progress,<br>every single day.</strong><p>Your future self will thank you.</p><a href="#planner">Make a plan ${arrow()}</a></div><button class="nav-link settings-link" data-action="settings">${icon('settings')}<span>Settings & progress</span></button><div class="sidebar-profile"><span class="avatar">S</span><div><strong>My study space</strong><small>Final exam preparation</small></div><span class="online-dot"></span></div></div>`;}
function topbar(){const parts=route.split('/');const s=parts[1]?bySubject(parts[1]):null;const title=routeTitle[parts[0]]||s?.shortTitle||'Study notes';$('#topbar').innerHTML=`<div class="topbar-left"><button class="icon-button menu-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumbs"><span>My workspace</span>${icon('chevron')}<strong>${esc(title)}</strong></div></div><div class="topbar-actions"><button id="search-open" class="search-trigger" data-action="search">${icon('search')}<span>Search anything</span><kbd>Ctrl K</kbd></button><button class="icon-button" data-action="theme" aria-label="Switch to ${state.theme==='dark'?'light':'dark'} theme">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="avatar" data-action="settings" aria-label="Open workspace settings">S</button></div>`;}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading-row"><div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function subjectOptions(current,all=true){return `${all?'<option value="all">All subjects</option>':''}${subjects.map(s=>`<option value="${s.id}" ${current===s.id?'selected':''}>${esc(s.shortTitle)}</option>`).join('')}`;}
function subjectChips(current,attr='subject-filter'){return `<div class="filter-chips"><button class="chip ${current==='all'?'active':''}" data-action="${attr}" data-id="all">All subjects</button>${subjects.map(s=>`<button class="chip ${current===s.id?'active':''}" data-action="${attr}" data-id="${s.id}">${esc(s.shortTitle)}</button>`).join('')}</div>`;}
function subjectCard(s){const p=pct(s),m=nextModule(s);return `<article class="subject-card" data-subject="${s.id}"><div class="subject-card-top"><span class="subject-icon">${icon(subjectIcons[s.id])}</span><span class="subject-code">${esc(s.code)}</span><span class="subject-menu">${s.modules.length} modules</span></div><a href="#subject/${s.id}" class="subject-title">${esc(s.shortTitle)}</a><p class="subject-description">${esc(s.description)}</p><div class="subject-meta"><span>${icon('book')}${s.modules.reduce((n,m)=>n+m.sections.length,0)} topics</span><span>${icon('target')}${s.questions.length} questions</span></div><div class="subject-progress"><span>Your progress</span><strong>${p}%</strong></div><div class="progress-line"><i style="width:${p}%"></i></div><div class="subject-footer"><span class="mini-pill">${icon('calendar')}${formatDate(s.examDate)}</span><a href="#read/${s.id}/${m.id}">${p?'Continue learning':'Start learning'} ${arrow()}</a></div></article>`;}
function weekly(){const out=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=dayKey(d),minutes=state.focusDays[key]||0;out.push(`<div class="week-day ${i===0?'today':''} ${minutes?'studied':''}" title="${minutes} focused minutes"><div class="week-bar" style="--bar-height:${Math.max(7,Math.min(100,minutes/Math.max(state.goal,1)*100))}%"><i></i></div><span>${d.toLocaleDateString('en',{weekday:'short',timeZone:'Asia/Colombo'}).slice(0,1)}</span></div>`);}return out.join('');}
function dashboard(){const seen=Object.values(state.read).filter(Boolean).length,answered=Object.keys(state.answers).length,correct=Object.values(state.answers).filter(a=>a.correct).length,total=modules.reduce((n,m)=>n+m.sections.length,0),p=Math.round(seen/total*100),today=state.focusDays[dayKey()]||0;const recent=state.lastModule&&byModule(state.lastModule),resume=recent||nextModule(subjects[0]),s=bySubject(resume.subjectId)||subjects[0];const upcoming=subjects.filter(s=>daysUntil(s.examDate)>=0).sort((a,b)=>a.examDate.localeCompare(b.examDate))[0];const taskMods=subjects.map(s=>({s,m:nextModule(s)}));return `${heading('LET’S MAKE TODAY COUNT',`A fresh start. A little closer. <span class="greeting-spark">✦</span>`,'Your notes, your practice, your progress. Everything you need to feel prepared.',`<span class="date-chip">${icon('calendar')}${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'Asia/Colombo'})}</span>`)}<div class="dashboard-grid"><div class="dashboard-main"><section class="welcome-card"><div class="hero-copy"><span class="tag"><span class="live-dot"></span> YOUR NEXT CHAPTER STARTS HERE</span><h2 class="hero-title">Big goals.<br>Small steps.<br><span>You’ve got this.</span></h2><p class="hero-text">Four subjects, one clear path. Turn your next study session into a little more confidence.</p><div class="hero-actions">${link(`Let’s get studying ${arrow()}`,`read/${s.id}/${resume.id}`)}<a class="hero-secondary" href="#planner">View study plan ${icon('chevron')}</a></div></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><span class="art-spark one">✦</span><span class="art-spark two">✧</span><div class="hero-book"><span class="book-spine"></span><span class="book-label">one step<br>at a time.</span>${icon('sparkles')}</div><span class="art-pill">${icon('check')} A little better, every day</span></div></section><div class="stats-grid">${[['book','purple',`${subjects.length}`,'Subjects, connected',`${modules.length} learning modules`],['target','blue',`${answered}`,'Questions practised',answered?`${Math.round(correct/answered*100)}% answer accuracy`:`${questions.length} ready to explore`],['chart','green',`${p}<small>%</small>`,'Overall progress',`${seen} of ${total} topics read`],['clock','orange',`${today}<small> min</small>`,'Focused today',`${state.goal} minute daily goal`]].map(([i,c,n,l,f])=>`<div class="stat-card"><span class="stat-icon ${c}">${icon(i)}</span><div class="stat-value">${n}</div><div class="stat-label">${l}</div><div class="stat-foot">${f}</div></div>`).join('')}</div><div class="section-heading"><div><h2>Your subjects <span class="count-badge">04</span></h2><p>A place for everything you’re learning.</p></div><a class="text-button" href="#subjects">View all ${arrow()}</a></div><div class="subject-grid">${subjects.map(subjectCard).join('')}</div><div class="section-heading"><div><h2>Pick your pace</h2><p>A different way to make it stick.</p></div></div><div class="quick-actions">${[['cards','Flip a few cards',`${cards.length} bite-sized moments of recall`,'flashcards','purple'],['target','Test what you know','A quick quiz. A clearer picture.','practice','blue'],['file','Think it through','Structured answers & exam rubrics','written','green']].map(([i,t,d,r,c])=>`<a class="quick-action ${c}" href="#${r}"><span class="stat-icon ${c}">${icon(i)}</span><h3>${t}</h3><p>${d}</p><span class="quick-arrow">${arrow()}</span></a>`).join('')}</div></div><aside class="dashboard-rail"><section class="panel focus-widget"><div class="panel-heading"><h2>${icon('clock')} Time to focus</h2><span class="badge">POMODORO</span></div><p>One thing at a time. You’re doing great.</p><div class="timer-ring"><div><div class="timer-time" id="timer-time">25:00</div><div class="timer-label" id="timer-label">FOCUS SESSION</div></div></div><div class="timer-presets"><button class="chip ${state.timer.duration===1500?'active':''}" data-action="timer-preset" data-minutes="25">25 min</button><button class="chip ${state.timer.duration===3000?'active':''}" data-action="timer-preset" data-minutes="50">50 min</button><button class="chip ${state.timer.duration===300?'active':''}" data-action="timer-preset" data-minutes="5">Break</button></div><div class="timer-controls">${btn(`${icon(state.timer.end?'pause':'play')}<span id="timer-button-label">${state.timer.end?'Pause session':'Start focus session'}</span>`,'timer-toggle','primary','id="timer-toggle"')}<button class="icon-button" data-action="timer-reset" aria-label="Reset focus timer">${icon('reset')}</button></div></section><section class="panel weekly-panel"><div class="panel-heading"><h2>This week</h2><span class="muted">Last 7 days</span></div><div class="week-days">${weekly()}</div><div class="week-summary"><span>${icon('flame')} Building your rhythm</span><strong>${Object.entries(state.focusDays).filter(([k,v])=>v>0&&k>=dayKey(new Date(Date.now()-6*86400000))).length}/7 days</strong></div></section><section class="panel"><div class="panel-heading"><h2>A little plan for today</h2><a class="text-button" href="#planner">${arrow()}</a></div><div class="today-tasks">${taskMods.slice(0,3).map(({s,m})=>`<a class="today-task" href="#read/${s.id}/${m.id}"><span class="task-subject-dot" data-subject="${s.id}"></span><div class="task-text"><strong>${esc(short(m.title,38))}</strong><span class="task-subtitle">${esc(s.shortTitle)} · ${m.sections.length} topics</span></div>${icon('chevron')}</a>`).join('')}</div></section>${upcoming?`<section class="exam-reminder"><span class="exam-reminder-icon">${icon('calendar')}</span><div><small>NEXT EXAM · ${formatDate(upcoming.examDate)}</small><strong>${esc(upcoming.shortTitle)}</strong><span>${examLabel(upcoming)}. One step at a time.</span></div></section>`:''}<div class="rail-quote">“You don’t have to see the whole staircase. Just take the first step.”<span>MAKE ROOM FOR PROGRESS.</span></div></aside></div>`;}
function subjectsPage(){return `${heading('YOUR LEARNING LIBRARY','Four subjects. One clear space.','Everything from your original study websites, brought together with care.')}<div class="subject-grid subject-grid-wide">${subjects.map(subjectCard).join('')}</div><section class="panel about-panel"><span class="stat-icon purple">${icon('layers')}</span><div><h2>Connected, from the source.</h2><p>${modules.length} modules, ${questions.length} questions, ${cards.length} flashcards and ${sources.length} source documents. Your original study files are preserved in the resource library.</p></div>${link('Browse resources '+arrow(),'library','button secondary')}</section>`;}
function subjectPage(id){const s=bySubject(id);if(!s)return notFound();return `${heading(esc(s.code)+' · YOUR SUBJECT',esc(s.title),esc(s.description),link(`${icon('target')} Practise this subject`,'practice?subject='+id,'button secondary'))}<div class="subject-banner" data-subject="${id}"><span class="subject-icon">${icon(subjectIcons[id])}</span><div><strong>${pct(s)}% of topics read</strong><span>${s.modules.length} modules · ${s.flashcards.length} flashcards · ${s.questions.length} practice questions</span></div><span class="mini-pill">${icon('calendar')} Exam ${formatDate(s.examDate)}</span></div><div class="section-heading"><h2>Your learning path</h2><a href="#flashcards?subject=${id}" class="text-button">Review flashcards ${arrow()}</a></div><div class="module-list">${s.modules.map((m,i)=>`<a class="module-row" href="#read/${id}/${m.id}"><span class="module-number ${modulePct(m)===100?'complete':''}">${modulePct(m)===100?icon('check'):String(i+1).padStart(2,'0')}</span><div class="module-detail"><h3>${esc(m.title)}</h3><p>${esc(short(m.subtitle||m.overview,160))}</p><div class="module-meta"><span>${m.sections.length} topics</span><span>${Math.max(5,Math.round(m.sections.reduce((n,x)=>n+plain(x.html).split(/\s+/).length,0)/180))} min read</span><span>${modulePct(m)}% complete</span></div></div><div class="module-action">${modulePct(m)?'Continue':'Explore'} ${arrow()}</div></a>`).join('')}</div>`;}
function refsHtml(refs){if(!refs?.length)return '';const seen=new Set();return `<div class="reference-list">${refs.map(r=>{let sid=r.sourceId||r.source;const source=sources.find(s=>s.id===sid||s.id.endsWith('-'+sid));if(!source)return '';const page=r.from||r.pages?.[0]||1;const isDocx=source.type==='docx'||source.filename.toLowerCase().endsWith('.docx');const label=`${short(source.title||source.filename,38)}${page?' · '+(isDocx?'block ':'p. ')+page:''}`;const key=source.id+page;if(seen.has(key))return '';seen.add(key);return `<a class="reference-chip" href="${esc(source.url)}${isDocx?'':'#page='+page}" target="_blank" rel="noopener" title="Open original source">${icon('file')}${esc(label)}${icon('external')}</a>`;}).join('')}</div>`;}
function reader(sid,mid){const s=bySubject(sid),m=byModule(mid);if(!s||!m||m.subjectId!==sid)return notFound();state.lastModule=mid;save();return `<div class="reader-top"><a class="text-button" href="#subject/${sid}">${icon('arrow','rotate-180')} ${esc(s.shortTitle)}</a><div class="reader-actions">${btn(icon('download')+' Print notes','print','ghost')}${btn(icon(state.saved[mid]?'check':'bookmark')+(state.saved[mid]?' Saved':' Save module'),'bookmark-module','secondary',`data-id="${mid}"`)}</div></div><div class="reader-layout"><aside class="reader-outline"><div class="eyebrow">IN THIS MODULE</div><h3>${esc(m.title)}</h3><div class="outline-progress">${modulePct(m)}% complete<div class="progress-line"><i style="width:${modulePct(m)}%"></i></div></div>${m.sections.map((x,i)=>`<a class="outline-link ${state.read[mid+':'+i]?'is-read':''}" href="#read/${sid}/${mid}" data-action="scroll-section" data-index="${i}"><span>${state.read[mid+':'+i]?icon('check'):String(i+1).padStart(2,'0')}</span>${esc(x.title)}</a>`).join('')}<a class="outline-bottom" href="#practice?subject=${sid}">${icon('target')} Put it into practice ${arrow()}</a></aside><div class="reader-main"><header class="reader-header"><div class="eyebrow">${esc(s.code)} · MODULE ${s.modules.findIndex(x=>x.id===mid)+1}</div><h1>${esc(m.title)}</h1><p>${esc(m.overview||m.subtitle)}</p><span class="badge">${m.sections.length} topics</span>${refsHtml((m.sourceIds||[]).map(sourceId=>({sourceId})))}</header><article class="reader-content article">${m.sections.map((x,i)=>`<section class="note-section" id="note-${i}"><div class="note-section-heading"><span class="note-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(x.title)}</h2><button class="icon-button bookmark-button ${state.saved[mid+':'+i]?'saved':''}" data-action="bookmark" data-id="${mid}:${i}" aria-label="${state.saved[mid+':'+i]?'Unsave':'Save'} topic">${icon('bookmark')}</button></div><div class="note-body">${x.html||'<p>Review the linked original source for this topic.</p>'}</div>${refsHtml(x.refs)}<label class="check-section"><input type="checkbox" data-action="read" data-module="${mid}" data-index="${i}" ${state.read[mid+':'+i]?'checked':''}> I’ve read and understood this topic</label></section>`).join('')}${m.pitfalls?.length?`<section class="callout"><h3>${icon('sparkles')} Watch out for these</h3><ul>${m.pitfalls.map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul></section>`:''}</article><section class="panel personal-notes"><div class="panel-heading"><h2>Make it your own.</h2><span class="badge">AUTOSAVED</span></div><p class="muted">A connection, a memory trick, a question for later. Leave yourself a note.</p><textarea class="input module-notes" data-action="module-note" data-id="${mid}" placeholder="Your thoughts belong here…" aria-label="My notes for this module">${esc(state.notes?.[mid]||'')}</textarea></section><div class="reader-end"><span class="stat-icon green">${icon('check')}</span><h2>A little more confident?</h2><p>Put what you’ve just learned into practice.</p><div class="page-actions">${link('Practise questions '+arrow(),'practice?subject='+sid)}${link('Next module '+icon('chevron'),`read/${sid}/${s.modules[(s.modules.findIndex(x=>x.id===mid)+1)%s.modules.length].id}`,'button secondary')}</div></div></div></div>`;}
function notFound(){return `<div class="empty-state">${icon('search')}<h1>That page isn’t here.</h1><p>Your subjects are one click away.</p>${link('Back to overview','dashboard')}</div>`;}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function practice(){const run=state.quizSession;if(!run)return practiceSetup();const qs=run.ids.map(byQuestion).filter(Boolean);if(!qs.length){state.quizSession=null;save();return practiceSetup();}if(run.finished)return quizResults(run,qs);const i=Math.min(run.index,qs.length-1),q=qs[i],answer=run.answers[q.id],revealed=answer!==undefined;return `${heading('A LITTLE PRACTICE GOES A LONG WAY','Trust what you’re learning.','Take your time. Every question is a chance to understand a little more.',btn('End session','quiz-end','ghost'))}<div class="practice-layout"><section class="quiz-panel"><div class="quiz-topline"><span class="badge">${esc(bySubject(q.subjectId).shortTitle)}</span><span class="muted">Question ${i+1} of ${qs.length}</span></div><div class="quiz-progress"><i style="width:${(i+1)/qs.length*100}%"></i></div><div class="question-number">QUESTION ${String(i+1).padStart(2,'0')}</div><h2 class="question-text">${esc(q.question)}</h2><div class="answers">${q.options.map((o,n)=>`<button class="answer-option ${revealed?(n===q.answer?'correct':n===answer?'incorrect':''):''}" data-action="quiz-answer" data-index="${n}" ${revealed?'disabled':''}><span class="option-letter">${String.fromCharCode(65+n)}</span><span>${esc(o)}</span>${revealed&&n===q.answer?icon('check'):''}</button>`).join('')}</div>${revealed?`<div class="answer-feedback ${answer===q.answer?'correct':'incorrect'}"><strong>${icon(answer===q.answer?'check':'help')}${answer===q.answer?'You’ve got it.':'A good one to come back to.'}</strong><p>${esc(q.explanation)}</p>${refsHtml(q.refs)}</div>`:'<p class="muted quiz-hint">Choose the answer that fits best.</p>'}<div class="quiz-footer"><span>${Object.keys(run.answers).length} answered · ${Object.entries(run.answers).filter(([id,a])=>byQuestion(id)?.answer===a).length} correct</span>${btn(i===qs.length-1?'See my results '+arrow():'Next question '+arrow(),'quiz-next','primary',revealed?'':'disabled')}</div></section><aside class="practice-aside panel"><span class="stat-icon purple">${icon('sparkles')}</span><h3>Progress over perfection.</h3><p>Read the explanation, even when you get it right. Understanding the “why” makes it stick.</p><div class="question-dots">${qs.map((x,n)=>`<span class="question-dot ${n===i?'current':''} ${run.answers[x.id]!==undefined?(run.answers[x.id]===x.answer?'correct':'incorrect'):''}">${n+1}</span>`).join('')}</div></aside></div>`;}
function practiceSetup(){const pool=questions.filter(q=>(quizSetup.subject==='all'||q.subjectId===quizSetup.subject)&&(quizSetup.mode!=='missed'||state.answers[q.id]?.correct===false));return `${heading('RECALL. REFLECT. REPEAT.','A little practice. A lot of clarity.',`${questions.length} questions across four subjects, with explanations that help things click.`)}<div class="practice-intro panel"><div class="practice-intro-copy"><span class="stat-icon purple">${icon('target')}</span><h2>What are we learning today?</h2><p>Build a quick session around your subject, or mix things up.</p></div><div class="quiz-setup"><label class="field-label">Choose a subject<select class="select" id="quiz-subject">${subjectOptions(quizSetup.subject)}</select></label><label class="field-label">Session length<select class="select" id="quiz-count">${[10,20,40].map(n=>`<option value="${n}" ${quizSetup.count===n?'selected':''}>${n} questions</option>`).join('')}<option value="0" ${quizSetup.count===0?'selected':''}>All available questions</option></select></label><label class="field-label">Question selection<select class="select" id="quiz-mode"><option value="all" ${quizSetup.mode==='all'?'selected':''}>All questions</option><option value="missed" ${quizSetup.mode==='missed'?'selected':''}>Questions I’ve missed</option></select></label><div class="setup-footer"><span class="muted">${pool.length} questions available</span>${btn('Start practising '+arrow(),'quiz-start','primary',pool.length?'':'disabled')}</div></div></div><div class="mode-grid">${subjects.map(s=>`<button class="mode-card" data-subject="${s.id}" data-action="quiz-subject" data-id="${s.id}"><span class="subject-icon">${icon(subjectIcons[s.id])}</span><h3>${esc(s.shortTitle)}</h3><p>${s.questions.length} questions · ${Object.keys(state.answers).filter(id=>s.questions.some(q=>q.id===id)).length} practised</p>${arrow()}</button>`).join('')}</div>`;}
function startQuiz(){let pool=questions.filter(q=>(quizSetup.subject==='all'||q.subjectId===quizSetup.subject)&&(quizSetup.mode!=='missed'||state.answers[q.id]?.correct===false));if(!pool.length){toast('No missed questions yet. Try all questions.');return;}state.quizSession={ids:shuffle(pool).slice(0,quizSetup.count||pool.length).map(q=>q.id),index:0,answers:{},finished:false};save();render();}
function quizResults(run,qs){const done=Object.keys(run.answers).length,score=qs.filter(q=>run.answers[q.id]===q.answer).length,percent=Math.round(score/Math.max(done,1)*100);return `${heading('EVERY SESSION IS A STEP FORWARD','Look how far you’ve come.','Take the useful bits with you, and give the tricky ones another go.')}<section class="results-card panel"><div class="score-ring" style="--score:${percent}%"><strong>${percent}<small>%</small></strong></div><h2>${percent>=80?'That’s a strong session.':percent>=50?'You’re building a solid foundation.':'You’ve found your next learning opportunity.'}</h2><p>${score} correct out of ${done} answered · ${qs.length} questions in this session</p><div class="page-actions">${btn('New practice session '+arrow(),'quiz-new')}${link('Review the notes','subjects','button secondary')}</div></section><div class="section-heading"><h2>Your session, explained</h2></div><div class="question-reviews">${qs.map(q=>`<details class="question-review"><summary><span class="review-status ${run.answers[q.id]===q.answer?'correct':'incorrect'}">${icon(run.answers[q.id]===q.answer?'check':'help')}</span><span>${esc(q.question)}</span>${icon('down')}</summary><div><p><strong>Your answer:</strong> ${run.answers[q.id]!==undefined?esc(q.options[run.answers[q.id]]):'Not answered'}</p><p><strong>Correct answer:</strong> ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p>${refsHtml(q.refs)}</div></details>`).join('')}</div>`;}
function filteredCards(){return cards.filter(c=>(cardFilter==='all'||c.subjectId===cardFilter)&&(cardReview!=='difficult'||state.cards[c.id]==='again')&&(cardReview!=='new'||!state.cards[c.id]));}
function flashcards(){const deck=filteredCards();if(cardIndex>=deck.length)cardIndex=0;const c=deck[cardIndex];return `${heading('MAKE A LITTLE KNOWLEDGE STICK','Small cards. Stronger recall.',`${cards.length} cards from your study material. Think of an answer, then turn the card.`)}<div class="flashcard-toolbar">${subjectChips(cardFilter,'card-filter')}<select class="select" id="card-review" aria-label="Filter flashcards"><option value="all" ${cardReview==='all'?'selected':''}>All cards</option><option value="new" ${cardReview==='new'?'selected':''}>Not reviewed yet</option><option value="difficult" ${cardReview==='difficult'?'selected':''}>Needs another look</option></select></div>${!c?`<div class="empty-state">${icon('check')}<h2>A clear deck.</h2><p>No cards in this view. Choose another filter to keep learning.</p>${btn('Show all cards','cards-all')}</div>`:`<div class="flashcard-stage"><div class="flashcard-stage-top"><span class="badge">${esc(bySubject(c.subjectId).shortTitle)}</span><span class="card-counter">${cardIndex+1} / ${deck.length}</span></div><button class="flashcard ${cardFlipped?'flipped':''}" id="flashcard" data-action="card-flip" aria-label="${cardFlipped?'Show question':'Reveal answer'}"><span class="flashcard-face"><span class="flashcard-label">${cardFlipped?'THE ANSWER':'A LITTLE MOMENT OF RECALL'}</span><span class="${cardFlipped?'flashcard-answer':'flashcard-question'}">${esc(cardFlipped?c.back:c.front)}</span><span class="flip-hint">${icon('reset')}${cardFlipped?'Click to see the question':'Click to reveal · Space to flip'}</span></span></button>${cardFlipped?`<div class="confidence-actions"><span>How did that feel?</span>${btn('Needs another look','card-rate','secondary','data-rating="again"')}${btn(icon('check')+' Got it!','card-rate','primary','data-rating="known"')}</div>`:'<p class="card-guidance muted">Give yourself a moment before you flip. You know more than you think.</p>'}<div class="flashcard-controls">${btn(icon('arrow','rotate-180')+' Previous','card-prev','ghost')}${btn(icon('reset')+' Shuffle','card-shuffle','ghost')}${btn('Next '+arrow(),'card-next','ghost')}</div><div class="deck-progress"><span>${deck.filter(c=>state.cards[c.id]==='known').length} mastered</span><div class="progress-line"><i style="width:${deck.filter(c=>state.cards[c.id]==='known').length/deck.length*100}%"></i></div><span>${deck.length} in this deck</span></div>${cardFlipped?refsHtml(c.refs):''}</div>`}`;}
let cardOrder=null;
function allPapers(){return subjects.flatMap(s=>s.papers.map(p=>({...p,subjectId:s.id})));}
function exams(){const session=state.examSession;if(session){const p=allPapers().find(p=>p.id===session.paperId);if(p)return session.finished?examResults(session,p):examRoom(session,p);}return `${heading('A DRESS REHEARSAL FOR EXAM DAY','Find your exam-day rhythm.','Six original mock papers. A quiet timer. Space to think clearly.')}<div class="callout exam-callout">${icon('help')}<p>Practice papers from your original study packs. MCQs are marked automatically; compare written responses with the included model answers and rubrics.</p></div><div class="exam-grid">${allPapers().map((p,i)=>{const s=bySubject(p.subjectId);return `<article class="exam-card panel" data-subject="${s.id}"><div class="subject-card-top"><span class="subject-icon">${icon(subjectIcons[s.id])}</span><span class="subject-code">${esc(s.code)}</span><span class="badge">PAPER ${i%2?'B':'A'}</span></div><span class="muted">${esc(s.shortTitle)}</span><h2>${esc(p.title)}</h2><p>${esc(p.description||'A full practice session that connects topics from across your subject.')}</p><div class="exam-meta"><span>${icon('clock')} ${p.duration||120} min</span><span>${p.mcqIds.length} MCQs</span><span>${p.writtenIds.length} written</span></div>${btn('Begin this paper '+arrow(),'exam-start','primary',`data-id="${p.id}"`)}</article>`;}).join('')}</div><div class="panel about-panel"><span class="stat-icon orange">${icon('briefcase')}</span><div><h3>Revising Enterprise Management?</h3><p>Your 50 MCQs and structured essay guides are ready in practice and written revision.</p></div>${link('Open essay guides '+arrow(),'written?subject=mem','button secondary')}</div>`;}
function examRoom(session,p){const qs=p.mcqIds.map(byQuestion).filter(Boolean),ws=p.writtenIds.map(byWritten).filter(Boolean);return `${heading('YOUR PRACTICE EXAM','One question at a time.',esc(p.title),`<span class="exam-timer badge" id="exam-timer">${icon('clock')} <span></span></span>${btn('Finish & review','exam-finish','primary')}`)}<div class="exam-autosave">${icon('check')} Answers save on this browser as you go. You can leave and come back.</div><section class="panel exam-section"><h2>Part A · Multiple choice</h2>${qs.map((q,i)=>`<div class="exam-question"><span class="eyebrow">QUESTION ${i+1}</span><h3>${esc(q.question)}</h3><div class="answers">${q.options.map((o,n)=>`<label class="answer-option ${session.answers[q.id]===n?'selected':''}"><input type="radio" name="${q.id}" value="${n}" data-action="exam-answer" data-id="${q.id}" ${session.answers[q.id]===n?'checked':''}><span class="option-letter">${String.fromCharCode(65+n)}</span><span>${esc(o)}</span></label>`).join('')}</div></div>`).join('')}</section><section class="panel exam-section"><h2>Part B · Written responses</h2><p class="muted">Work from memory. Model answers and marking guides become available after submission.</p>${ws.map((w,i)=>`<div class="exam-question"><span class="eyebrow">QUESTION ${i+1}${w.marks?' · '+w.marks+' MARKS':''}</span><h3>${esc(w.question)}</h3><textarea class="input written-answer" data-action="exam-written" data-id="${w.id}" placeholder="Build your answer here…" aria-label="Answer to written question ${i+1}">${esc(session.written[w.id]||'')}</textarea></div>`).join('')}</section><div class="page-actions exam-final-action">${btn('Finish & review my paper '+arrow(),'exam-finish')}</div>`;}
function examResults(session,p){const qs=p.mcqIds.map(byQuestion).filter(Boolean),ws=p.writtenIds.map(byWritten).filter(Boolean),correct=qs.filter(q=>session.answers[q.id]===q.answer).length;return `${heading('REHEARSAL COMPLETE','Take a breath. You showed up.',esc(p.title),btn('Choose another paper','exam-new','secondary'))}<section class="panel results-card"><span class="stat-icon green">${icon('graduate')}</span><h2>${correct} / ${qs.length} MCQs correct</h2><p>${Math.round(correct/Math.max(qs.length,1)*100)}% in multiple choice. Review your written work separately using the marking guides below.</p><p class="muted">Written marks are self-assessed. They are not included in your MCQ score.</p></section><div class="section-heading"><h2>Part A · Answer review</h2></div>${qs.map((q,i)=>`<details class="question-review"><summary><span class="review-status ${session.answers[q.id]===q.answer?'correct':'incorrect'}">${icon(session.answers[q.id]===q.answer?'check':'help')}</span><span>${i+1}. ${esc(q.question)}</span>${icon('down')}</summary><div><p><strong>Your answer:</strong> ${session.answers[q.id]!==undefined?esc(q.options[session.answers[q.id]]):'Not answered'}</p><p><strong>Correct answer:</strong> ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p>${refsHtml(q.refs)}</div></details>`).join('')}<div class="section-heading"><h2>Part B · Reflect on your responses</h2></div>${ws.map((w,i)=>`<details class="question-review"><summary><span class="review-status">${i+1}</span><span>${esc(w.question)}</span>${icon('down')}</summary><div><h4>Your response</h4><p class="user-response">${esc(session.written[w.id]||'No response recorded.')}</p><h4>Model answer & marking guide</h4><div class="article rubric">${w.answerHtml}</div>${refsHtml(w.refs)}</div></details>`).join('')}`;}
function writtenPage(){const ws=written.filter(w=>writtenFilter==='all'||w.subjectId===writtenFilter);return `${heading('GO BEYOND THE RIGHT ANSWER','Put your thinking into words.',`${written.length} tutorials, structured questions and essay guides with model responses.`)}${subjectChips(writtenFilter,'written-filter')}<div class="toolbar"><span class="muted">${ws.length} questions · Click a question to explore its model answer</span></div><div class="written-list">${ws.map((w,i)=>`<details class="question-review"><summary><span class="review-status">${String(i+1).padStart(2,'0')}</span><span>${esc(w.question)}<small>${esc(bySubject(w.subjectId).shortTitle)}${w.marks?' · '+w.marks+' marks':''}${w.kind?' · '+esc(w.kind):''}</small></span>${icon('down')}</summary><div><label class="field-label">Try answering from memory<textarea class="input written-answer" data-action="written-draft" data-id="${w.id}" placeholder="Your answer saves automatically…">${esc(state.drafts?.[w.id]||'')}</textarea></label><details class="model-answer"><summary>Reveal model answer & marking guide ${icon('down')}</summary><div class="article rubric">${w.answerHtml}</div>${refsHtml(w.refs)}</details></div></details>`).join('')}</div>${subjects.filter(s=>writtenFilter==='all'||s.id===writtenFilter).flatMap(s=>s.bonus||[]).filter(b=>b.html).map(b=>`<details class="question-review"><summary>${esc(b.title)}${icon('down')}</summary><div class="article">${b.html}</div></details>`).join('')}`;}
function library(){const filtered=sources.filter(x=>(libraryFilter==='all'||x.subjectId===libraryFilter)&&(!libraryQuery||`${x.title} ${x.filename}`.toLowerCase().includes(libraryQuery.toLowerCase())));return `${heading('BACK TO THE SOURCE','Your entire resource shelf.','Original lectures, tutorials and labs. A source for every deeper question.')}<div class="library-toolbar">${subjectChips(libraryFilter,'library-filter')}<label class="search-input">${icon('search')}<input id="library-search" type="search" placeholder="Find a resource…" value="${esc(libraryQuery)}" aria-label="Search resources"></label></div><div class="toolbar"><span class="muted">${filtered.length} of ${sources.length} documents</span><span class="muted">${icon('check')} Source files preserved</span></div><div class="library-grid">${filtered.map(x=>`<article class="source-card" data-subject="${x.subjectId}"><span class="source-icon">${icon('file')}</span><div class="source-info"><span class="subject-code">${esc(bySubject(x.subjectId).shortTitle)}</span><h3>${esc(x.title||x.filename)}</h3><p>${esc(x.filename.split('.').pop().toUpperCase())}${x.units?' · '+x.units+' source units':''}</p></div><div class="source-actions"><a class="button secondary small" href="${esc(x.url)}" target="_blank" rel="noopener">Open ${icon('external')}</a><a class="icon-button" href="${esc(x.originalUrl||x.url)}" download aria-label="Download ${esc(x.filename)}">${icon('download')}</a></div></article>`).join('')}</div>${!filtered.length?'<div class="empty-state"><h2>No resources found.</h2><p>Try a different search or subject.</p></div>':''}`;}
let planSubject='all',planTab='checklist';
function planner(){const visible=subjects.filter(s=>planSubject==='all'||s.id===planSubject),allTasks=visible.flatMap(s=>s.tasks.map(t=>({...t,subjectId:s.id}))),done=allTasks.filter(t=>state.checks[t.id]).length;return `${heading('MAKE SPACE FOR WHAT MATTERS','Your plan. At your pace.','Keep the next step clear, and celebrate the small things you finish.',btn(icon('plus')+' Add a task','add-task','primary'))}<div class="exam-timeline">${[...subjects].sort((a,b)=>a.examDate.localeCompare(b.examDate)).map(s=>`<div class="timeline-item" data-subject="${s.id}"><span class="timeline-dot"></span><small>${formatDate(s.examDate)}</small><strong>${esc(s.shortTitle)}</strong><span>${examLabel(s)}</span></div>`).join('')}</div><div class="planner-toolbar">${subjectChips(planSubject,'plan-filter')}<div class="tab-buttons"><button class="chip ${planTab==='checklist'?'active':''}" data-action="plan-tab" data-id="checklist">Checklist</button><button class="chip ${planTab==='schedule'?'active':''}" data-action="plan-tab" data-id="schedule">Original study plans</button></div></div>${state.customTasks.length?`<section class="panel personal-tasks"><div class="panel-heading"><h2>My own next steps</h2><span class="badge">${state.customTasks.filter(t=>state.checks[t.id]).length}/${state.customTasks.length}</span></div>${state.customTasks.map(t=>taskRow(t)).join('')}</section>`:''}${planTab==='checklist'?`<div class="progress-summary"><span>${done} of ${allTasks.length} steps complete</span><div class="progress-line"><i style="width:${done/Math.max(1,allTasks.length)*100}%"></i></div><strong>${Math.round(done/Math.max(1,allTasks.length)*100)}%</strong></div><div class="planner-grid">${visible.map(s=>`<section class="panel plan-panel" data-subject="${s.id}"><div class="panel-heading"><h2><span class="subject-icon small">${icon(subjectIcons[s.id])}</span>${esc(s.shortTitle)}</h2><span class="badge">${s.tasks.filter(t=>state.checks[t.id]).length}/${s.tasks.length}</span></div><div class="checklist">${s.tasks.map(t=>taskRow(t,s.id)).join('')}</div></section>`).join('')}</div>`:`<div class="planner-grid">${visible.map(s=>`<section class="panel plan-panel"><div class="panel-heading"><h2>${esc(s.shortTitle)}</h2><span class="badge">${s.plan.length} sessions</span></div>${s.plan.length?s.plan.map((d,i)=>`<div class="plan-row"><span class="date-badge">${d.date?`<small>${formatDate(d.date,{month:'short'})}</small>${formatDate(d.date,{day:'numeric'})}`:String(i+1).padStart(2,'0')}</span><div><h3>${esc(d.title||d.focus||'Study session '+(i+1))}</h3><p>${esc(d.description||d.focus||'')}</p>${d.tasks?.length?`<ul>${d.tasks.map(t=>`<li>${esc(t.title||t.label)}</li>`).join('')}</ul>`:''}${d.moduleId&&byModule(d.moduleId)?link('Open module '+arrow(),`read/${s.id}/${d.moduleId}`,'text-button'):''}${d.time?`<small class="muted">${esc(d.time)}</small>`:''}</div></div>`).join(''):'<div class="empty-state"><p>Use this subject’s checklist to build your own pace.</p></div>'}</section>`).join('')}</div>`}`;}
function taskRow(t,sid=''){const m=byModule(t.moduleId);return `<div class="task-row ${state.checks[t.id]?'done':''}"><input type="checkbox" id="check-${t.id}" data-action="task-check" data-id="${t.id}" ${state.checks[t.id]?'checked':''}><label class="task-text" for="check-${t.id}"><strong>${esc(t.title)}</strong>${t.detail?`<span class="task-subtitle">${esc(t.detail)}</span>`:''}</label>${m?`<a href="#read/${sid||m.subjectId}/${m.id}" class="icon-button" aria-label="Read module">${icon('chevron')}</a>`:''}${t.custom?`<button class="icon-button" data-action="delete-task" data-id="${t.id}" aria-label="Delete task">${icon('close')}</button>`:''}</div>`;}
function saved(){const items=Object.keys(state.saved).filter(k=>state.saved[k]).map(k=>{const[mid,index]=k.split(':');const m=byModule(mid);return m?{m,index:index!==undefined?Number(index):null}:null;}).filter(Boolean);return `${heading('KEEP THE GOOD BITS CLOSE','A shelf for your lightbulb moments.','Saved modules and topics, ready when you need another look.')}<div class="module-list">${items.map(({m,index})=>`<div class="module-row"><span class="subject-icon" data-subject="${m.subjectId}">${icon('bookmark')}</span><div class="module-detail"><a href="#read/${m.subjectId}/${m.id}${index!==null?'?section='+index:''}"><h3>${esc(index!==null?m.sections[index]?.title:m.title)}</h3></a><p>${esc(bySubject(m.subjectId).shortTitle)} · ${esc(m.title)}</p></div><button class="icon-button bookmark-button saved" data-action="bookmark" data-id="${m.id}${index!==null?':'+index:''}" aria-label="Remove bookmark">${icon('close')}</button></div>`).join('')}</div>${!items.length?`<div class="empty-state"><span class="stat-icon purple">${icon('bookmark')}</span><h2>Something worth coming back to.</h2><p>Tap the bookmark beside any topic or save an entire module. You’ll find it right here.</p>${link('Explore your subjects '+arrow(),'subjects')}</div>`:''}`;}
let modalPreviousFocus=null;
function modal(title,html,cls=''){modalPreviousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button modal-close" data-action="modal-close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${html}</div></section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('.modal input, .modal button, .modal select')?.focus(),0);}
function closeModal(){if(!$('#modal-root').children.length)return;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');modalPreviousFocus?.focus?.();}
function settings(){modal('Make this space yours.',`<p class="muted">Your progress lives in this browser. Export a backup to bring it to another device.</p><div class="settings-group"><h3>A calmer view</h3>${btn(icon(state.theme==='dark'?'sun':'moon')+' Switch to '+(state.theme==='dark'?'light':'dark')+' theme','theme','secondary')}</div><div class="settings-group"><h3>Daily focus goal</h3><label class="field-label">Minutes per day<select class="select" id="focus-goal">${[25,45,60,90,120].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} minutes</option>`).join('')}</select></label></div><div class="settings-group"><h3>Keep your progress</h3><div class="page-actions">${btn(icon('download')+' Export progress','export','secondary')}${btn(icon('folder')+' Import backup','import','secondary')}</div><input type="file" id="import-progress" accept="application/json,.json" hidden><p class="muted">Includes reading progress, saved notes, answers, drafts, tasks and focus sessions.</p></div><div class="settings-group"><h3>A fresh start</h3><p class="muted">Clear your study progress on this browser. Export a backup first if you’d like to keep it.</p>${btn('Reset my progress','reset-confirm','danger')}</div><div class="settings-note">${icon('keyboard')} <span>Ctrl / ⌘ K to search · Space to flip a flashcard</span></div>`);}
function buildSearchIndex(){if(searchIndex)return;searchIndex=[...subjects.map(s=>({type:'Subject',title:s.title,sub:s.code,subject:s.id,route:'subject/'+s.id,icon:subjectIcons[s.id]})),...modules.flatMap(m=>m.sections.map((x,i)=>({type:'Topic',title:x.title,sub:bySubject(m.subjectId).shortTitle+' · '+m.title,subject:m.subjectId,route:`read/${m.subjectId}/${m.id}?section=${i}`,text:plain(x.html),icon:'book'}))),...questions.map(q=>({type:'Question',title:q.question,sub:bySubject(q.subjectId).shortTitle,subject:q.subjectId,id:q.id,text:q.explanation,icon:'target'})),...cards.map(c=>({type:'Flashcard',title:c.front,sub:bySubject(c.subjectId).shortTitle,subject:c.subjectId,id:c.id,text:c.back,icon:'cards'})),...sources.map(s=>({type:'Resource',title:s.title,sub:bySubject(s.subjectId).shortTitle,subject:s.subjectId,url:s.url,text:s.filename,icon:'file'}))].map(x=>({...x,haystack:`${x.title} ${x.sub} ${x.text||''}`.toLowerCase()}));}
function openSearch(){buildSearchIndex();modal('A little help finding things.',`<label class="search-input global-search-input">${icon('search')}<input id="global-search" type="search" placeholder="Search topics, questions, cards, resources…" autocomplete="off" aria-label="Search all study material"></label><div id="search-results" class="search-results"></div><div class="search-footer"><span>SEARCH ACROSS YOUR ENTIRE WORKSPACE</span><kbd>Esc to close</kbd></div>`,'search-modal');searchResults('');setTimeout(()=>$('#global-search')?.focus(),0);}
let currentSearchResults=[];
function searchResults(query){const terms=query.toLowerCase().trim().split(/\s+/).filter(Boolean);currentSearchResults=terms.length?searchIndex.filter(x=>terms.every(t=>x.haystack.includes(t))).sort((a,b)=>(b.title.toLowerCase().includes(query.toLowerCase())?1:0)-(a.title.toLowerCase().includes(query.toLowerCase())?1:0)).slice(0,24):searchIndex.filter(x=>x.type==='Subject');$('#search-results').innerHTML=currentSearchResults.length?`${!terms.length?'<p class="search-section-label">JUMP INTO A SUBJECT</p>':''}${currentSearchResults.map((x,i)=>`<button class="search-result" data-action="search-result" data-index="${i}"><span class="search-result-icon">${icon(x.icon)}</span><span class="search-result-body"><strong>${esc(short(x.title,120))}</strong><small>${esc(x.type)} · ${esc(short(x.sub,85))}</small></span>${icon('arrow')}</button>`).join('')}`:'<div class="empty-state"><h3>No matches yet.</h3><p>Try another word, like “firewall”, “risk” or “marketing”.</p></div>';}
function closeSidebar(){document.body.classList.remove('sidebar-open');$('.menu-toggle')?.setAttribute('aria-expanded','false');}
function render(preserveScroll=false){const top=preserveScroll?window.scrollY:0;const raw=location.hash.slice(1)||'dashboard';const [path,query='']=raw.split('?');route=path.replace(/^\//,'');const params=new URLSearchParams(query),parts=route.split('/');if(raw!==appliedHash&&params.has('subject')){const id=params.get('subject');if(bySubject(id)){if(parts[0]==='practice')quizSetup.subject=id;if(parts[0]==='flashcards'){cardFilter=id;cardIndex=0;}if(parts[0]==='written')writtenFilter=id;}}
appliedHash=raw;sidebar();topbar();document.documentElement.dataset.theme=state.theme;let content;switch(parts[0]){case'dashboard':content=dashboard();break;case'subjects':content=subjectsPage();break;case'subject':content=subjectPage(parts[1]);break;case'read':content=reader(parts[1],parts[2]);break;case'practice':content=practice();break;case'flashcards':content=flashcards();break;case'exams':content=exams();break;case'written':content=writtenPage();break;case'library':content=library();break;case'planner':content=planner();break;case'saved':content=saved();break;default:content=notFound();}
$('#main').innerHTML=`<div class="page ${parts[0]==='read'?'reading-page':''}" data-page="${parts[0]}">${content}</div>`;document.title=(parts[0]==='read'?byModule(parts[2])?.title:routeTitle[parts[0]]||bySubject(parts[1])?.title||'StudyOS')+' — StudyOS';window.scrollTo({top,behavior:'instant'});updateTimers();if(parts[0]==='read'&&params.has('section'))setTimeout(()=>$('#note-'+Number(params.get('section')))?.scrollIntoView({block:'start'}),30);}
function updateTimers(){const t=state.timer;if(t.end){t.remaining=Math.max(0,Math.ceil((t.end-Date.now())/1000));if(t.remaining<=0){const isBreak=t.duration<=300;if(!isBreak){state.focusDays[dayKey()]=(state.focusDays[dayKey()]||0)+Math.round(t.duration/60);activity('clock','Completed a '+Math.round(t.duration/60)+'-minute focus session');}t.end=null;t.remaining=t.duration;save();toast(isBreak?'Break complete. Ready for your next small step?':'Session complete. That’s time well spent.');if(route==='dashboard')render(true);}}
const el=$('#timer-time');if(el){const secs=t.end?t.remaining:t.remaining??t.duration;el.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;$('#timer-label').textContent=t.duration<=300?'A MOMENT TO RECHARGE':t.end?'YOU’RE MAKING PROGRESS':'FOCUS SESSION';$('.timer-ring').style.setProperty('--timer-progress',`${(t.duration-secs)/t.duration*100}%`);}
const ex=state.examSession;if(ex&&!ex.finished){const seconds=Math.max(0,Math.ceil((ex.end-Date.now())/1000));const el=$('#exam-timer span');if(el)el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(!seconds){ex.finished=true;save();toast('Time is up. Your paper is saved for review.');if(route==='exams')render(true);}}}
function toggleBookmark(id){state.saved[id]=!state.saved[id];save();toast(state.saved[id]?'Saved to your notes shelf.':'Removed from saved notes.');const top=window.scrollY;render(true);window.scrollTo(0,top);}
function answerQuiz(index){const run=state.quizSession;if(!run||run.finished)return;const q=byQuestion(run.ids[run.index]);if(!q||run.answers[q.id]!==undefined)return;run.answers[q.id]=index;state.answers[q.id]={selected:index,correct:index===q.answer,date:new Date().toISOString()};save();render(true);}
function finishQuiz(){const run=state.quizSession;if(!run)return;run.finished=true;activity('target','Completed a '+Object.keys(run.answers).length+'-question practice session');save();render();}
function selectCard(delta=1){cardIndex=(cardIndex+delta+Math.max(filteredCards().length,1))%Math.max(filteredCards().length,1);cardFlipped=false;render(true);}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='studyos-progress-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Your progress backup is ready.');}
const actions={
'menu':()=>{document.body.classList.toggle('sidebar-open');$('.menu-toggle')?.setAttribute('aria-expanded',document.body.classList.contains('sidebar-open'));},
'search':openSearch,'settings':settings,'modal-close':closeModal,
'theme':()=>{state.theme=state.theme==='dark'?'light':'dark';save();const inSettings=!!$('#focus-goal');render(true);if(inSettings)settings();},
'print':()=>window.print(),
'bookmark':el=>toggleBookmark(el.dataset.id),'bookmark-module':el=>toggleBookmark(el.dataset.id),
'scroll-section':el=>$('#note-'+el.dataset.index)?.scrollIntoView({behavior:'smooth',block:'start'}),
'quiz-start':startQuiz,'quiz-answer':el=>answerQuiz(Number(el.dataset.index)),
'quiz-next':()=>{const r=state.quizSession;if(!r||r.answers[r.ids[r.index]]===undefined)return;if(r.index>=r.ids.length-1)finishQuiz();else{r.index++;save();render();}},
'quiz-end':()=>{if(Object.keys(state.quizSession?.answers||{}).length)finishQuiz();else{state.quizSession=null;save();render();}},
'quiz-new':()=>{state.quizSession=null;save();render();},
'quiz-subject':el=>{quizSetup.subject=el.dataset.id;render();},
'card-filter':el=>{cardFilter=el.dataset.id;cardIndex=0;cardFlipped=false;render(true);},
'card-flip':()=>{cardFlipped=!cardFlipped;render(true);},
'card-next':()=>selectCard(1),'card-prev':()=>selectCard(-1),
'card-rate':el=>{const c=filteredCards()[cardIndex];if(!c)return;state.cards[c.id]=el.dataset.rating;save();toast(el.dataset.rating==='known'?'A little knowledge, locked in.':'Saved for another look.');if(filteredCards().some(x=>x.id===c.id))selectCard(1);else{cardIndex%=Math.max(1,filteredCards().length);cardFlipped=false;render(true);}},
'card-shuffle':()=>{cards.splice(0,cards.length,...shuffle(cards));cardIndex=0;cardFlipped=false;render(true);toast('A fresh order. Let’s keep going.');},
'cards-all':()=>{cardReview='all';cardIndex=0;render();},
'library-filter':el=>{libraryFilter=el.dataset.id;render(true);},
'written-filter':el=>{writtenFilter=el.dataset.id;render(true);},
'plan-filter':el=>{planSubject=el.dataset.id;render(true);},
'plan-tab':el=>{planTab=el.dataset.id;render(true);},
'add-task':()=>modal('One small next step.',`<form id="task-form"><label class="field-label">What would you like to work on?<input class="input" id="task-title" required maxlength="200" placeholder="e.g. Review firewall rules for 20 minutes"></label><div class="modal-footer"><button type="button" class="button secondary" data-action="modal-close">Cancel</button><button class="button primary" type="submit">Add to my plan ${icon('plus')}</button></div></form>`),
'delete-task':el=>{state.customTasks=state.customTasks.filter(t=>t.id!==el.dataset.id);delete state.checks[el.dataset.id];save();render(true);},
'exam-start':el=>{const p=allPapers().find(p=>p.id===el.dataset.id);if(!p)return;state.examSession={paperId:p.id,start:Date.now(),end:Date.now()+(p.duration||120)*60000,answers:{},written:{},finished:false};save();render();},
'exam-finish':()=>modal('Ready to review your paper?',`<p>Your responses will be saved and the timer will stop. You can then compare each response with its model answer.</p><div class="modal-footer">${btn('Keep working','modal-close','secondary')}${btn('Finish & review','exam-submit')}</div>`),
'exam-submit':()=>{if(!state.examSession)return;state.examSession.finished=true;activity('file','Completed a mock exam');save();closeModal();render();},
'exam-new':()=>{state.examSession=null;save();render();},
'timer-toggle':()=>{const t=state.timer;if(t.end){t.remaining=Math.max(0,Math.ceil((t.end-Date.now())/1000));t.end=null;}else t.end=Date.now()+t.remaining*1000;save();render(true);},
'timer-reset':()=>{state.timer.end=null;state.timer.remaining=state.timer.duration;save();render(true);},
'timer-preset':el=>{const n=Number(el.dataset.minutes)*60;state.timer={duration:n,remaining:n,end:null};save();render(true);},
'export':exportProgress,'import':()=>$('#import-progress')?.click(),
'reset-confirm':()=>modal('Start with a clear page?',`<p>This clears your reading progress, saved notes, practice answers, drafts and personal tasks on this browser. You can export a backup before resetting.</p><div class="modal-footer">${btn('Keep my progress','modal-close','secondary')}${btn('Export backup','export','secondary')}${btn('Reset progress','reset-progress','danger')}</div>`),
'reset-progress':()=>{const theme=state.theme;state=defaults();state.theme=theme;save();closeModal();render();toast('A fresh start. Your study material is all here.');},
'search-result':el=>{const r=currentSearchResults[Number(el.dataset.index)];if(!r)return;if(r.route)navigate(r.route);else if(r.type==='Resource'){window.open(r.url,'_blank','noopener');closeModal();}else if(r.type==='Question'){state.quizSession={ids:[r.id],index:0,answers:{},finished:false};save();navigate('practice');}else if(r.type==='Flashcard'){cardFilter=r.subject;cardReview='all';cardFlipped=false;cardIndex=filteredCards().findIndex(c=>c.id===r.id);navigate('flashcards');}},
};
document.addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop')){closeModal();return;}const el=event.target.closest('[data-action]');if(!el||el.disabled||['INPUT','TEXTAREA','SELECT'].includes(el.tagName))return;const fn=actions[el.dataset.action];if(fn){event.preventDefault();fn(el,event);}else if(el.closest('.sidebar'))closeSidebar();});
document.addEventListener('change',event=>{const el=event.target;const action=el.dataset.action;if(action==='read'){const id=el.dataset.module+':'+el.dataset.index;state.read[id]=el.checked;if(el.checked)activity('book','Read '+byModule(el.dataset.module).sections[el.dataset.index].title);save();const outline=$$('.outline-link')[Number(el.dataset.index)];if(outline){outline.classList.toggle('is-read',el.checked);outline.querySelector('span').innerHTML=el.checked?icon('check'):String(Number(el.dataset.index)+1).padStart(2,'0');}const progress=$('.outline-progress');if(progress)progress.innerHTML=`${modulePct(byModule(el.dataset.module))}% complete<div class="progress-line"><i style="width:${modulePct(byModule(el.dataset.module))}%"></i></div>`;}
if(action==='task-check'){state.checks[el.dataset.id]=el.checked;save();const focusId=el.id;render(true);document.getElementById(focusId)?.focus({preventScroll:true});}
if(action==='exam-answer'){const run=state.examSession;if(run&&!run.finished){run.answers[el.dataset.id]=Number(el.value);save();$$(`input[name="${el.name}"]`).forEach(x=>x.closest('.answer-option').classList.toggle('selected',x.checked));}}
if(el.id==='quiz-subject'){quizSetup.subject=el.value;render(true);}if(el.id==='quiz-count'){quizSetup.count=Number(el.value);render(true);}if(el.id==='quiz-mode'){quizSetup.mode=el.value;render(true);}if(el.id==='card-review'){cardReview=el.value;cardIndex=0;cardFlipped=false;render(true);}if(el.id==='focus-goal'){state.goal=Number(el.value);save();render(true);toast('Your daily focus goal is set.');}
if(el.id==='import-progress'&&el.files[0]){const file=el.files[0];if(file.size>10*1024*1024){toast('This file is too large for a progress backup.');return;}file.text().then(t=>{try{const value=JSON.parse(t);if(value.version!==1||typeof value.read!=='object'||!value.read||!value.timer||!Array.isArray(value.activity)||!Array.isArray(value.customTasks))throw Error();state={...defaults(),...value};save();closeModal();render();toast('Welcome back. Your progress is restored.');}catch{toast('That isn’t a valid StudyOS backup. Please use an exported progress file.');}});}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search')searchResults(el.value);if(el.id==='library-search'){libraryQuery=el.value;const start=el.selectionStart;render(true);const x=$('#library-search');x.focus();if(x.type!=='search')x.setSelectionRange(start,start);}
if(el.dataset.action==='module-note'){state.notes??={};state.notes[el.dataset.id]=el.value;save();}if(el.dataset.action==='exam-written'&&state.examSession&&!state.examSession.finished){state.examSession.written[el.dataset.id]=el.value;save();}if(el.dataset.action==='written-draft'){state.drafts??={};state.drafts[el.dataset.id]=el.value;save();}});
document.addEventListener('submit',event=>{if(event.target.id!=='task-form')return;event.preventDefault();const title=$('#task-title').value.trim();if(!title)return;state.customTasks.push({id:'custom-'+Date.now(),title,custom:true});save();closeModal();render(true);toast('One clear next step, added.');});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();return;}if(event.key==='Escape'){closeModal();closeSidebar();}const currentModal=$('.modal');if(event.key==='Tab'&&currentModal){const focusable=$$('button:not([disabled]),a[href],input:not([hidden]),select,textarea',currentModal);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
if(route==='flashcards'&&!currentModal&&!['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(document.activeElement.tagName)){if(event.code==='Space'){event.preventDefault();actions['card-flip']();}if(event.key==='ArrowRight')selectCard(1);if(event.key==='ArrowLeft')selectCard(-1);}});
$('#mobile-overlay').addEventListener('click',closeSidebar);
window.addEventListener('hashchange',()=>{closeSidebar();closeModal();render();});
window.addEventListener('beforeunload',save);
window.APP={get state(){return state;},navigate,render,subjects,modules,questions,cards,written,sources};
render();setInterval(updateTimers,1000);
})();
